// MCU descriptions chosen in the native window: the former manual Playwright scenario (tests/ui/mcu.playwright.cjs),
// now run by CTest without Node.js (issue #34). It selects the built-in chip, loads descriptions by file and by text,
// runs a firmware on a loaded chip, shows a validation error, retries a failed chip request and returns to the catalog.
//
// The system file dialog is not driven (see files.spec.js): the spec hands the input a File and dispatches `change`.
// window.sfFixtures is generated by tests/CMakeLists.txt from mcus/atmega328p.json and firmware/prebuilt/blink.hex.
// The application is one shared simulation: run the specs in the order written.
jasmine.getEnv().configure({random: false});
jasmine.DEFAULT_TIMEOUT_INTERVAL = 30000;

describe("MCU descriptions in the window", () => {
  const sf = () => window.siliconForge;
  const fixtures = window.sfFixtures;
  const $ = (selector) => document.querySelector(selector);
  const texts = (selector) => Array.from(document.querySelectorAll(selector), (e) => e.textContent);
  const selectedText = () => $("#mcu-select").selectedOptions[0]?.text;
  const chipName = () => $("#breadboard .bb-chip-name")?.textContent;

  /** Resolves when `predicate()` holds, polling the page for at most `timeoutMs`. */
  const until = async (predicate, what, timeoutMs = 10000) => {
    const deadline = performance.now() + timeoutMs;
    while (!predicate()) {
      if (performance.now() > deadline) throw new Error(`timeout waiting for ${what}`);
      await new Promise((resolve) => setTimeout(resolve, 20));
    }
  };

  /** Gives the MCU file input a description, as the chooser would. */
  const chooseMcu = (name, description) => {
    const transfer = new DataTransfer();
    transfer.items.add(new File([JSON.stringify(description)], name, {type: "application/json"}));
    $("#mcu-file").files = transfer.files;
    $("#mcu-file").dispatchEvent(new Event("change", {bubbles: true}));
  };

  /** The ATmega168 derived from the shipped ATmega328P, as docs/MCU-DESCRIPTIONS.md describes it. */
  const atmega168 = () => {
    const d = structuredClone(fixtures.mcu);
    d.name = "ATmega168";
    d.memories.flash.size = 16384;
    d.memories.sram.size = 1024;
    d.memories.eeprom.size = 512;
    d.registers.SPH.reset = 4;
    return d;
  };

  const errors = [];
  const onError = (event) => errors.push(event.message ?? String(event.reason));
  beforeAll(() => {
    window.addEventListener("error", onError);
    window.addEventListener("unhandledrejection", onError);
  });
  afterAll(() => {
    window.removeEventListener("error", onError);
    window.removeEventListener("unhandledrejection", onError);
  });

  it("selects the built-in chip and draws its 28 pins", async () => {
    await sf().selectMcu("atmega328p");
    await until(() => sf().state.mcu === "ATmega328P", "the ATmega328P");
    await until(() => $("#breadboard svg"), "the breadboard");
    expect((await sf().chip()).pins.length).toBe(28);
  });

  it("tells a modified file from the catalog entry that has the same name", async () => {
    await sf().loadMcu(JSON.stringify({...fixtures.mcu, clockHz: 8000000}));
    await until(() => sf().state.clockHz === 8000000 && sf().state.mcuId === null, "the loaded description");
    await until(() => $("#mcu-select").value === "__loaded__", "the loaded entry in the selector");
    expect(selectedText()).toBe("ATmega328P (loaded)");
    await sf().selectMcu("AtMega328P");  // Catalog names are matched without regard to case.
    await until(() => sf().state.clockHz === 16000000 && sf().state.mcuId === "atmega328p", "the catalog ATmega328P");
    await until(() => $("#mcu-select").value === "atmega328p", "the catalog entry in the selector");
  });

  it("does not rewrite the selector while its value is unchanged", async () => {
    const select = $("#mcu-select");
    const value = Object.getOwnPropertyDescriptor(HTMLSelectElement.prototype, "value");
    let writes = 0;
    Object.defineProperty(select, "value", {
      configurable: true,
      get() { return value.get.call(this); },
      set(next) { ++writes; value.set.call(this, next); },
    });
    try {
      await sf().run();
      await new Promise((resolve) => setTimeout(resolve, 150));  // Several frames.
    } finally {
      delete select.value;
      await sf().pause();
    }
    expect(writes).toBe(0);
  });

  it("selects exact server IDs, whatever the display names", () => {
    const select = $("#mcu-select");
    const option = new Option("Catalog entry", "MiXeD");
    const original = sf().state;
    select.add(option);
    try {
      sf().onState(JSON.stringify({...original, mcu: "Unrelated display name", mcuId: "MiXeD", serial: ""}));
      expect(select.value).toBe("MiXeD");
    } finally {
      sf().onState(JSON.stringify({...original, serial: ""}));
      option.remove();
    }
  });

  it("loads a chip chosen by file, with its breadboard and pinout", async () => {
    chooseMcu("atmega168.json", atmega168());
    await until(() => sf().state.mcu === "ATmega168", "the ATmega168");
    await until(() => selectedText() === "ATmega168 (loaded)", "the loaded entry in the selector");
    await until(() => chipName() === "atmega168", "the chip on the breadboard");
    $("#tab-pinout").click();
    await until(() => $('#pinout svg[aria-label="ATmega168 pinout"]'), "the ATmega168 pinout");
  });

  it("runs a firmware on the loaded chip", async () => {
    await sf().load("blink.hex", new TextEncoder().encode(fixtures.hex));
    await sf().setSpeed(10);
    await sf().run();
    await until(() => sf().state.cycles > 20000000, "20 M cycles", 20000);
    expect(sf().state.mcu).toBe("ATmega168");
  });

  it("shows the JSON path of an invalid description and keeps the running chip", async () => {
    const malformed = atmega168();
    const adc = malformed.peripherals.findIndex((p) => p.type === "avr.adc");
    expect(adc).toBeGreaterThanOrEqual(0);
    malformed.peripherals[adc].vector = "missing";
    chooseMcu("bad.json", malformed);
    await until(() => $("#mcu-error").textContent.includes(`/peripherals/${adc}/vector`), "the validation error");
    expect(sf().state.mcu).toBe("ATmega168");
  });

  it("retries a failed chip request and shows the generic labels of a chip without a circuit", async () => {
    const bare = atmega168();
    delete bare.breadboard;
    bare.name = "BareAVR";
    const labels = {PB0: "PB10", PB1: "PB2", PB2: "AVCC", PB3: "AREF"};
    for (const pin of bare.package.pins) if (labels[pin.port]) pin.label = labels[pin.port];
    // The first chip request after the replacement fails; a later frame must retry it.
    const original = sf().chip;
    let attempts = 0;
    sf().chip = () => (++attempts === 1 ? Promise.reject(new Error("test: transient chip failure")) : original());
    try {
      await sf().loadMcu(JSON.stringify(bare));
      await until(() => $("#mcu-error").textContent === "test: transient chip failure", "the transient failure");
      await until(() => $('#pinout svg[aria-label="BareAVR pinout"]'), "the BareAVR pinout");
      await until(() => $("#mcu-error").hidden, "the error cleared");
    } finally {
      sf().chip = original;
    }
    // A chip the circuit was not made for sits alone on a bare board.
    await until(() => chipName() === "bareavr", "the chip on a bare board");
    await until(() => !$("#breadboard .bb-led"), "a board without its LED");
    await until(() => selectedText() === "BareAVR (loaded)", "the loaded entry in the selector");
    expect(attempts).toBeGreaterThanOrEqual(2);
    // The pin list is cleared when the chip changes and filled again by a later frame.
    await until(() => texts("#digital .pin .label").includes("AVCC"), "the pin list of the BareAVR");
    const pinLabels = texts("#digital .pin .label");
    expect(pinLabels).toContain("AVCC");
    expect(pinLabels).toContain("AREF");
    expect(pinLabels.indexOf("PB2")).toBeLessThan(pinLabels.indexOf("PB10"));
    expect(texts("#analog .pin .label").every((label) => /^A\d+$/.test(label))).toBe(true);
  });

  it("returns to the catalog chip from the selector", async () => {
    await sf().pause();
    $("#mcu-select").value = "atmega328p";
    $("#mcu-select").dispatchEvent(new Event("change", {bubbles: true}));
    await until(() => sf().state.mcu === "ATmega328P", "the ATmega328P");
    await until(() => $("#mcu-select").value === "atmega328p", "the catalog entry in the selector");
    await until(() => chipName() === "atmega328p", "the chip on the breadboard");
    expect(errors).toEqual([]);
  });
});
